#include <Arduino.h>

const uint8_t sensorPins[5] = {A0, A1, A2, A3, A4};
const uint8_t ledPins[5] = {2, 3, 4, 5, 6};

void setup() {
  for (uint8_t i = 0; i < 5; ++i) {
    pinMode(sensorPins[i], INPUT);
    pinMode(ledPins[i], OUTPUT);
    digitalWrite(ledPins[i], LOW);
  }
}

void loop() {
  for (uint8_t i = 0; i < 5; ++i) {
    int reading = analogRead(sensorPins[i]);
    digitalWrite(ledPins[i], reading > 500 ? HIGH : LOW);
  }
}
